function isExpired(trialEndsAt, clock) {
  return clock() > trialEndsAt;
}

function makeStubGateway() {
  return {
    refund(chargeId) {
      return { success: true };
    },
  };
}

function makeLog() {
  const calls = [];
  return {
    calls,
    refund(chargeId) {
      calls.push(chargeId);
    },
  };
}

function makeStore() {
  const items = [];
  return {
    save(item) {
      items.push(item);
    },
    all() {
      return [...items];
    },
  };
}

function expiredIds(users, clock) {
  return users.filter((u) => clock() > u.trialEndsAt).map((u) => u.id);
}

function createGatewaySpy() {
  const calls = [];
  return {
    calls,
    refund(chargeId) {
      calls.push({ method: "refund", args: [chargeId] });
      return { success: true };
    },
  };
}

function createFakeGateway() {
  const refunds = [];
  return {
    refund(chargeId) {
      refunds.push(chargeId);
      return { success: true, chargeId };
    },
    getRefunds() {
      return [...refunds];
    },
  };
}

function refundExpiredTrials(users, clock, gateway) {
  const refunded = [];
  for (const user of users) {
    if (clock() > user.trialEndsAt && user.pendingChargeId) {
      gateway.refund(user.pendingChargeId);
      refunded.push(user.id);
    }
  }
  return refunded;
}
